<?php
declare(strict_types=1);
namespace App;
final class UserService {
 public static function save(?int $id,array $input):int {RoleService::admin();return DB::transaction(function($p)use($id,$input):int {$p->query('SELECT id FROM identity_write_guard WHERE id=1 FOR UPDATE')->fetchColumn();$old=null;if($id){$q=$p->prepare('SELECT * FROM users WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch()?:throw new \RuntimeException('Пользователь не найден.',404);if((int)$old['version']!==(int)($input['expected_revision']??$input['version']??0))throw new \RuntimeException('Данные уже изменены в другом окне.',409);}
 $username=trim((string)($input['username']??$old['username']??''));$name=trim((string)($input['display_name']??$input['name']??''));$role=(string)($input['role']??'');$active=isset($input['is_active'])||isset($input['active'])?1:0;$password=(string)($input['new_password']??$input['password']??'');
 if(!preg_match('/^[a-zA-Z0-9_.-]{3,80}$/D',$username)||$name===''||mb_strlen($name)>160)throw new \RuntimeException('Проверьте логин и имя пользователя.',422);$q=$p->prepare('SELECT id FROM roles WHERE id=?');$q->execute([$role]);if(!$q->fetchColumn())throw new \RuntimeException('Неизвестная роль.',422);$q=$p->prepare('SELECT id FROM users WHERE username=? AND id<>?');$q->execute([$username,$id??0]);if($q->fetchColumn())throw new \RuntimeException('Такой логин уже используется.',422);
 if(!$old||$password!==''){if(strlen($password)<12||strlen($password)>4096)throw new \RuntimeException('Пароль должен содержать не менее 12 символов.',422);if(array_key_exists('confirm_password',$input)&&$password!==(string)$input['confirm_password'])throw new \RuntimeException('Пароли не совпадают.',422);}
 if($old&&$old['role']==='admin'&&(int)$old['active']===1&&($role!=='admin'||!$active)){if((int)$p->query("SELECT COUNT(*) FROM users WHERE role='admin' AND active=1")->fetchColumn()<=1)throw new \RuntimeException('Нельзя отключить последнего активного Администратора.',422);}
 if($old){$sql='UPDATE users SET username=?,name=?,role=?,active=?,version=version+1';$values=[$username,$name,$role,$active];if($password!==''){$sql.=',password_hash=?,auth_version=auth_version+1';$values[]=password_hash($password,PASSWORD_DEFAULT);}$values[]=$id;$p->prepare($sql.' WHERE id=?')->execute($values);}else{$p->prepare('INSERT INTO users(username,name,password_hash,role,active) VALUES(?,?,?,?,?)')->execute([$username,$name,password_hash($password,PASSWORD_DEFAULT),$role,$active]);$id=(int)$p->lastInsertId();}
 People::reset();Audit::record($old?'user.update':'user.create','user',$id,$old?['username'=>$old['username'],'name'=>$old['name'],'role'=>$old['role'],'active'=>$old['active'],'version'=>$old['version']]:null,['username'=>$username,'name'=>$name,'role'=>$role,'active'=>$active,'password_changed'=>$password!=='']);return $id;
 });}
}
